
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_mn12_sx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_mn12_sx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.442657412096693e+00, -3.503274850134657e+00, -3.569290666558155e+00, -3.622970438002885e+00, -3.622953813547636e+00, -3.489845487602586e+00, -3.109266102740650e+00, -2.422530139494552e+00, -1.647635434250442e+00, -1.047941157541412e+00, -4.217730795336749e-01, -3.687324154558839e-01, -4.675516999931486e-01, -3.857620687957564e-01, -2.987471141414591e-01, -1.871320874807857e-01, 1.583960790205286e-02, 2.345675661838840e-02, 5.576344891466379e-03, 6.676421792286939e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


